insert:
Connections {
target: dmpDialog
onOptionMenuBack: {
decrementLevel()
}
}
function decrementLevel() {
base.closed()
}
function selectFilteredRow(index) {
var row=tempModel.get(index)
if(!row)return
if(row.goTo){base.closed();cassetteMainWindow.openGoTo();return}
base.selected(row.originalIndex)
base.accepted()
}
ListModel {
id: tempModel
function createData() {
tempModel.clear()
if (base.model !== null) {
var i
var list_count = base.model.count()
for (i = 0; i < list_count; i++) {
if (base.model.level(i) === 1) {
var label=String(base.model.listData(i))
var go=typeof cassetteMainWindow!=="undefined" && typeof cassetteMainWindow.isGoToRow==="function" && cassetteMainWindow.isGoToRow(base.model.listIndex(i),label)
var kind=PathLabels.kind(label,qsTr("020031"))
var nav=kind===1
if(kind===2)continue
tempModel.append({goTo:go,list_data: go ? "Go to" : nav ? "Audio Path" : label, originalIndex: base.model.listIndex(i),
level: base.model.level(i),
groupL1: base.model.parentIndex(i),
type: base.model.type(i),
coverIcon:base.model.coverIcon(i)})
}
}
}
}
}
Rectangle {
id: opacityArea
anchors { fill: parent; bottomMargin: p.bottomSpace; }
opacity: 0.0
MouseArea {
anchors.fill: parent
onClicked: {
console.log("opacity area click")
base.closed()
}
}
}
Item {
id: menuArea
height: levelOneMenu.height
width: levelOneMenu.width
anchors {
bottom: base.bottom; right: base.right;
bottomMargin: p.menuBottomSpace; rightMargin: p.menu_right_margin;
}
clip: true
OptionMenuList {
id: levelOneMenu
x: 0
height: (p.visibleAreaCellCount < tempModel.count )? p.menu_max_height : (levelOneMenu.cell_height * tempModel.count) + (p.menu_separator_height * (tempModel.count - 1)) + p.menu_vertical_margin
anchors { bottom: parent.bottom; right: parent.right; }
model: tempModel
visible_area_cell_count: p.visibleAreaCellCount
onClicked: {
base.selectFilteredRow(index)
}
}
}
QtObject {
id: p
property int visibleAreaCellCount: 6
property int bottomSpace: 56
property int menuBottomSpace: 90
property int menu_right_margin: 24
property int menu_vertical_margin: 5 * 2
property int menu_separator_height: 1
property int menu_max_height: 581
}
}
